func TestBhvSerializationobject003_ObjectSerializer_Deserialize_DateTimeWithoutAnOffsetIsRejected(t *testing.T) {
	t.Parallel()
	for _, wire := range []string{
		`"2024-01-01T10:00:00"`,
		`"2024-01-01"`,
		`"2024-01-01 10:00:00+00:00"`,
		`"2024-01-01T10:00:00.123"`,
	} {
		var model models.EdgeCases
		err := deserialize([]byte(`{"expiresAt":`+wire+`}`), &model)
		var serErr *SerializationError
		if !errors.As(err, &serErr) {
			t.Errorf("expected *SerializationError for %s, got %T: %v", wire, err, err)
		}
	}
}

