// An optional scalar parameter is held as a pointer; stringify must send the
// pointed-to value, never the pointer address that %v prints.
func TestBhvSerializationobject118_ObjectSerializer_Stringify_OptionalScalarPointers(t *testing.T) {
	t.Parallel()
	i32, i64, n := int32(7), int64(-42), 5
	f64, f32 := 1.5, float32(2.5)
	whole := 2.0
	yes, no := true, false
	cases := []struct {
		name  string
		value any
		want  string
	}{
		{"int", &n, "5"},
		{"int32", &i32, "7"},
		{"int64", &i64, "-42"},
		{"float64", &f64, "1.5"},
		{"float32", &f32, "2.5"},
		{"whole float64", &whole, "2.0"},
		{"bool true", &yes, "true"},
		{"bool false", &no, "false"},
	}
	for _, tc := range cases {
		if got := stringify(tc.value); got != tc.want {
			t.Errorf("%s: stringify = %q, want %q", tc.name, got, tc.want)
		}
	}
}

