// ── Scenario 2: non-lowercase string enum (Availability) preserves wire casing ──
//
// Availability declares "Available", "Sold", and the hyphenated "on-hold". The
// wire casing/spelling must round-trip exactly (no lowercasing, no identifier
// mangling leaking to the wire), a known value must resolve to its member, and
// an undeclared value must be rejected on deserialize.

func TestBhvSerializationobject109_ObjectSerializer_AvailabilityEnum_PreservesWireCasingRoundTrip(t *testing.T) {
	t.Parallel()
	for _, v := range []models.Availability{
		models.AvailabilityAvailable,
		models.AvailabilitySold,
		models.AvailabilityOnHold,
	} {
		data, err := serialize(v)
		if err != nil {
			t.Fatalf("unexpected error serializing %v: %v", v, err)
		}
		expected := "\"" + string(v) + "\""
		if string(data) != expected {
			t.Errorf("expected wire casing preserved as %s, got %q", expected, string(data))
		}
		var back models.Availability
		if err := deserialize(data, &back); err != nil {
			t.Fatalf("unexpected error round-tripping %v: %v", v, err)
		}
		if back != v {
			t.Errorf("round-trip mismatch: expected %v, got %v", v, back)
		}
	}
}

// F1144: the members whose wire values hold a quote, a backslash, a dollar and
// a brace sequence round-trip exactly, with the wire text JSON-escaped only
// where JSON requires it.
func TestBhvSerializationobject076_ObjectSerializer_AvailabilityEnum_HostileMembersRoundTripExactly(t *testing.T) {
	t.Parallel()
	cases := []struct {
		value models.Availability
		wire  string
	}{
		{models.AvailabilityOclock, `"o'clock"`},
		{models.AvailabilityAB, `"a\\b"`},
		{models.AvailabilityEq, `"$eq"`},
		{models.AvailabilityX, `"#{x}"`},
	}
	for _, tc := range cases {
		data, err := serialize(tc.value)
		if err != nil {
			t.Fatalf("unexpected error serializing %v: %v", tc.value, err)
		}
		if string(data) != tc.wire {
			t.Errorf("expected %s on the wire, got %s", tc.wire, data)
		}
		var back models.Availability
		if err := deserialize([]byte(tc.wire), &back); err != nil {
			t.Fatalf("unexpected error decoding %s: %v", tc.wire, err)
		}
		if back != tc.value {
			t.Errorf("round-trip mismatch: expected %q, got %q", tc.value, back)
		}
	}
}

